source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');suppressPackageStartupMessages(library(Seurat))
a<-rd('analysis_cell_metadata.tsv.gz');o<-qread(objpath,nthreads=1);x<-LayerData(o,assay='RNA',layer='data');ct<-LayerData(o,assay='RNA',layer='counts')
# Appropriate T lineage excludes NK from the shared T/NK major annotation.
z<-a[analysis_major_c2l_final=='T/NK'&analysis_celltype_c2l_final!='NK'];setorder(z,barcode);set.seed(123);z[,priority:=runif(.N)];setorder(z,sample_uid,priority,barcode);z[,train:=seq_len(.N)<=100,by=sample_uid];tr<-z[train==TRUE];expr<-x[,tr$barcode,drop=FALSE];keep<-Matrix::rowSums(expr>0)>=max(3,ceiling(.01*ncol(expr)));expr<-expr[keep,,drop=FALSE]
put(z,'scenic_membership_T_lineage.tsv.gz');put(data.table(gene=rownames(expr)),'scenic_genes_T_lineage.tsv');fwrite(data.table(gene=rownames(expr),as.data.table(as.matrix(expr))),file.path(B,'objects/scenic/T_lineage_training.tsv.gz'),sep='\t',compress='gzip')
au<-rd('scenic_training_audit.tsv');au[lineage=='T_lineage',`:=`(n_full=nrow(z),n_training=nrow(tr),n_genes=nrow(expr),n_specimens=uniqueN(z$sample_uid),gene_hash=digest(rownames(expr),algo='sha256'),training_hash=digest(tr$barcode,algo='sha256'))];put(au,'scenic_training_audit.tsv')
old<-fread(file.path(P,'mp10_subtype_screen_round1/tables/epithelial_existing_metadata.tsv.gz'),select=c('cell_id','epi_allgene_cluster','annotation'));setnames(old,'cell_id','barcode');e<-merge(a[analysis_major_c2l_final=='Epithelial'],old,by='barcode',all.x=TRUE);cover<-e[,.(n_cells=.N),by=epi_allgene_cluster];cover[,fraction:=n_cells/sum(n_cells)];cover[,major_cluster:=!is.na(epi_allgene_cluster)&fraction>=.05];put(cover,'epi_existing_cluster_coverage.tsv');m<-rd('pseudobulk_membership.tsv.gz')[profile_type%in%c('H50','H10','H05','L50')];m<-merge(m,e[,.(barcode,epi_allgene_cluster)],by='barcode');m<-m[epi_allgene_cluster%in%cover[major_cluster==TRUE,epi_allgene_cluster]];m[,cluster_profile:=paste(profile_id,epi_allgene_cluster,sep='|')];lev<-sort(unique(m$cluster_profile));map<-sparseMatrix(i=match(m$barcode,colnames(ct)),j=match(m$cluster_profile,lev),x=1,dims=c(ncol(ct),length(lev)))
genes<-c('NECTIN2','PVR','VEGFA','VEGFB','VEGFC','PGF','MDK','MIF','LGALS9','TGFB1','TGFB2','ANGPT1','ANGPT2','CXCL12');genes<-intersect(genes,rownames(ct));cm<-ct[genes,,drop=FALSE];um<-cm%*%map;cm@x[]<-1;det<-cm%*%map;nm<-x[genes,,drop=FALSE]%*%map
pp<-m[,.(n_cells=.N),by=.(cluster_profile,sample_uid,profile_type,epi_allgene_cluster)][match(lev,cluster_profile)];q<-rd('specimen_exposure_eligibility.tsv');pp<-merge(pp,q[,.(sample_uid,dataset,patient_uid_recorded,main_patient)],by='sample_uid',sort=FALSE);pp<-pp[match(lev,cluster_profile)];out<-rbindlist(lapply(seq_along(genes),function(i){d<-copy(pp);d[,`:=`(gene=genes[i],total_UMI=as.numeric(um[i,]),positive_fraction=as.numeric(det[i,])/n_cells,normalized_mean=as.numeric(nm[i,])/n_cells)];d}));put(out,'epi_within_cluster_candidate_expression.tsv.gz')
st<-list();for(h in c('H50','H10','H05'))for(n in c(50,30))for(cl in unique(out$epi_allgene_cluster))for(g in genes){v<-out[main_patient&epi_allgene_cluster==cl&gene==g&n_cells>=n];hi<-v[profile_type==h,.(sample_uid,high=normalized_mean)];lo<-v[profile_type=='L50',.(sample_uid,low=normalized_mean)];j<-merge(hi,lo,by='sample_uid');st[[length(st)+1]]<-data.table(high_definition=h,min_cells=n,cluster=cl,gene=g,n_pairs=nrow(j),median_normalized_difference=if(nrow(j))median(j$high-j$low)else NA_real_,p=if(nrow(j)>=4 && any(j$high!=j$low))wilcox.test(j$high,j$low,paired=TRUE,exact=FALSE)$p.value else NA_real_,status=if(nrow(j)>=4)'completed'else'not_evaluable')};st<-rbindlist(st);st[,q:=p.adjust(p,'BH'),by=.(high_definition,min_cells)];put(st,'epi_within_cluster_candidate_changes.tsv')
put(e[,.(n_cells=.N,MP10_logCount_rho=cor(MP10_cell,log1p(nCount_RNA),method='spearman'),MP10_nFeature_rho=cor(MP10_cell,nFeature_RNA,method='spearman')),by=sample_uid],'epi_score_quality_correlations.tsv')
